INSERT INTO `space_versions` (`version`, `title`, `summary`, `created_at`) VALUES ('v136', '调整线改细、直接拖动更平滑、侧边框加线、应用随高度自适应', '三条调整线全部改细并常显：菜单栏与最近聊天栏之间的横线、菜单栏右边缘的竖线、智能体列表栏右边缘的竖线，都只有 1px、只比底色深一点，直接按住拖动就能调整两个窗口的比例和各栏宽度，不再需要长按约半秒、也不用先开任何开关（设置「窗口大小」页的开关已去掉）。拖动改为逐帧平滑跟随，不再一卡一卡；往下拖横线时，上方的应用会自动摊开、均匀适配新的高度，不会挤在顶部留一截空白，往上拖又会收回。拖宽度的竖线只改宽度，不会再顺带把菜单高度固定住。松手自动保存，退出再进保持调整后的样子。', strftime('%s','now') * 1000);
